-- v0.8.158 pharmacy reporting views and conversion RPC. Applied to linked Anaira clinic project.
-- Views use security_invoker so source table RLS remains effective.
create or replace view public.pharmacy_supplier_balances with (security_invoker=true) as select l.clinic_id,l.supplier_id,s.supplier_name,coalesce(sum(l.debit),0)::numeric(14,2) total_debit,coalesce(sum(l.credit),0)::numeric(14,2) total_credit,(coalesce(sum(l.debit),0)-coalesce(sum(l.credit),0))::numeric(14,2) outstanding,min(l.entry_date) filter(where l.debit>l.credit) oldest_unsettled_entry from public.pharmacy_supplier_ledger l join public.pharmacy_suppliers s on s.id=l.supplier_id and s.clinic_id=l.clinic_id group by l.clinic_id,l.supplier_id,s.supplier_name;
create or replace view public.pharmacy_supplier_ageing with (security_invoker=true) as select l.clinic_id,l.supplier_id,s.supplier_name,sum(case when l.entry_date>current_date-30 then l.debit-l.credit else 0 end)::numeric(14,2) days_0_30,sum(case when l.entry_date<=current_date-30 and l.entry_date>current_date-60 then l.debit-l.credit else 0 end)::numeric(14,2) days_31_60,sum(case when l.entry_date<=current_date-60 and l.entry_date>current_date-90 then l.debit-l.credit else 0 end)::numeric(14,2) days_61_90,sum(case when l.entry_date<=current_date-90 then l.debit-l.credit else 0 end)::numeric(14,2) days_over_90,sum(l.debit-l.credit)::numeric(14,2) outstanding from public.pharmacy_supplier_ledger l join public.pharmacy_suppliers s on s.id=l.supplier_id and s.clinic_id=l.clinic_id group by l.clinic_id,l.supplier_id,s.supplier_name;
create or replace view public.pharmacy_sales_cogs with (security_invoker=true) as select a.clinic_id,a.invoice_id,i.invoice_no,a.invoice_item_id,a.medication_id,m.name medicine_name,sum(a.dispensed_quantity)::numeric(14,3) sold_quantity,sum(a.dispensed_quantity*b.purchase_rate)::numeric(14,2) cogs,sum(a.dispensed_quantity*ii.unit_price)::numeric(14,2) gross_sales,(sum(a.dispensed_quantity*ii.unit_price)-sum(a.dispensed_quantity*b.purchase_rate))::numeric(14,2) gross_margin,min(a.created_at) dispensed_at from public.pharmacy_dispense_allocations a join public.inventory_batches b on b.id=a.batch_id and b.clinic_id=a.clinic_id join public.invoices i on i.id=a.invoice_id and i.clinic_id=a.clinic_id join public.invoice_items ii on ii.id=a.invoice_item_id and ii.clinic_id=a.clinic_id join public.medications m on m.id=a.medication_id and m.clinic_id=a.clinic_id group by a.clinic_id,a.invoice_id,i.invoice_no,a.invoice_item_id,a.medication_id,m.name;
create or replace view public.pharmacy_reorder_suggestions with (security_invoker=true) as select m.clinic_id,m.id medication_id,m.name,m.sku,m.barcode,coalesce(sum(b.quantity_on_hand) filter(where coalesce(b.stock_condition,'saleable')='saleable' and (b.expiry_date is null or b.expiry_date>=current_date)),0)::numeric(14,3) saleable_stock,coalesce(m.reorder_level,0)::numeric(14,3) reorder_level,greatest(coalesce(m.reorder_quantity,0),coalesce(m.reorder_level,0)-coalesce(sum(b.quantity_on_hand) filter(where coalesce(b.stock_condition,'saleable')='saleable' and (b.expiry_date is null or b.expiry_date>=current_date)),0),0)::numeric(14,3) suggested_order_qty from public.medications m left join public.inventory_batches b on b.medication_id=m.id and b.clinic_id=m.clinic_id where m.active=true group by m.clinic_id,m.id,m.name,m.sku,m.barcode,m.reorder_level,m.reorder_quantity;
create or replace view public.pharmacy_expiry_register with (security_invoker=true) as select b.clinic_id,b.id batch_id,b.medication_id,m.name medicine_name,b.batch_number,b.expiry_date,b.quantity_on_hand,b.purchase_rate,case when b.expiry_date<current_date then 'expired' when b.expiry_date<=current_date+30 then '0-30 days' when b.expiry_date<=current_date+60 then '31-60 days' when b.expiry_date<=current_date+90 then '61-90 days' else 'over 90 days' end expiry_bucket from public.inventory_batches b join public.medications m on m.id=b.medication_id and m.clinic_id=b.clinic_id where b.quantity_on_hand>0;
